import{_ as l,o as i,c as t,a2 as o}from"./chunks/framework.CvydjLy7.js";const g=JSON.parse('{"title":"篇章地图与学习路径","description":"","frontmatter":{"title":"篇章地图与学习路径"},"headers":[{"level":2,"title":"四个阶段","slug":"四个阶段","link":"#四个阶段","children":[]},{"level":2,"title":"各篇要点","slug":"各篇要点","link":"#各篇要点","children":[{"level":3,"title":"起步","slug":"起步","link":"#起步","children":[]},{"level":3,"title":"核心能力","slug":"核心能力","link":"#核心能力","children":[]},{"level":3,"title":"工程化","slug":"工程化","link":"#工程化","children":[]},{"level":3,"title":"全端交付","slug":"全端交付","link":"#全端交付","children":[]}]},{"level":2,"title":"阅读建议","slug":"阅读建议","link":"#阅读建议","children":[]}],"relativePath":"guide/roadmap.md","filePath":"guide/roadmap.md","lastUpdated":1789497795000}'),a={name:"guide/roadmap.md"};function r(d,e,n,c,s,u){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="篇章地图与学习路径" tabindex="-1">篇章地图与学习路径 <a class="header-anchor" href="#篇章地图与学习路径" aria-label="Permalink to &quot;篇章地图与学习路径&quot;">​</a></h1><h2 id="四个阶段" tabindex="-1">四个阶段 <a class="header-anchor" href="#四个阶段" aria-label="Permalink to &quot;四个阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>篇章</th><th>内容</th><th>产出</th></tr></thead><tbody><tr><td>一 · 起步</td><td>第 0 – 2 篇</td><td>4.x 相对 3.x 变了什么、环境准备、Maven 构建、代码分层、自动配置与依赖注入</td><td>一个能跑起来的 REST 接口</td></tr><tr><td>二 · 核心能力</td><td>第 3 – 8 篇</td><td>配置管理、Profiles、日志、Web 层、安全认证、数据访问、缓存与校验、消息通信</td><td>带认证、能读写数据库、有缓存的完整后端</td></tr><tr><td>三 · 工程化</td><td>第 9 – 11 篇</td><td>测试策略、可观测性与监控、打包与容器化部署</td><td>可测试、可监控、可部署的制品</td></tr><tr><td>四 · 全端交付</td><td>第 12 – 13 篇</td><td>Vue 3 + Element Plus 管理端、接口联调、认证贯通、一体化部署</td><td>前后端分离、能交付使用的全端项目</td></tr></tbody></table><h2 id="各篇要点" tabindex="-1">各篇要点 <a class="header-anchor" href="#各篇要点" aria-label="Permalink to &quot;各篇要点&quot;">​</a></h2><h3 id="起步" tabindex="-1">起步 <a class="header-anchor" href="#起步" aria-label="Permalink to &quot;起步&quot;">​</a></h3><p><strong>第 0 篇 · <a href="/backend-engineering-course/ch00/">开篇：版本核实与学习地图</a></strong></p><ul><li>4.1.1 是不是最新稳定版——版本核实的三种可靠手段</li><li>3.x 到 4.x 的破坏性变更全景：starter 改名、模块拆分、Jackson 3、测试包迁移</li><li>环境准备：JDK、Maven、IDE，以及国内镜像加速</li><li>贯穿全教程的案例项目与技术选型</li></ul><p><strong>第 1 篇 · <a href="/backend-engineering-course/ch01/">入门：环境、构建系统与第一个应用</a></strong></p><ul><li>官方入门教程的完整复现，逐行解释每个注解的作用</li><li>Maven 构建系统：parent、starter、插件三件套；Gradle 对照写法</li><li>starter 命名体系在 4.x 的变化与选择建议</li><li>可执行 jar 的原理与热部署（DevTools）</li></ul><p><strong>第 2 篇 · <a href="/backend-engineering-course/ch02/">工程结构、自动配置与依赖注入</a></strong></p><ul><li>主类为什么必须放在根包：组件扫描、实体扫描、仓库扫描的实际范围</li><li>分层组织（web / service / repository / domain / dto）与按领域组织的取舍</li><li>自动配置的运作机制、条件注解、按需替换与排除</li><li>Bean 与依赖注入：构造器注入、多个候选 Bean 的抉择、Bean 生命周期</li></ul><h3 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h3><p><strong>第 3 篇 · <a href="/backend-engineering-course/ch03/">核心特性：外部化配置、Profiles 与日志</a></strong></p><ul><li>配置的十来种来源与优先级；<code>@Value</code> 在多环境项目里为什么会失控</li><li><code>@ConfigurationProperties</code> 的类型安全绑定、校验与 IDE 提示元数据</li><li>Profiles 的四种激活方式，生产环境的配置分离策略</li><li>日志：级别调整、日志分组、JSON 结构化输出、文件滚动</li><li>JSON 序列化（Jackson 3 的迁移要点）、国际化、AOP、任务调度</li></ul><p><strong>第 4 篇 · <a href="/backend-engineering-course/ch04/">Web 层：MVC、REST 接口与异常处理</a></strong></p><ul><li>REST 接口的分层设计：控制器只做协议转换，业务规则放 Service</li><li>统一响应体与全局异常处理；HTTP 状态码与业务错误码的分工</li><li>参数校验：内置注解、分组校验、自定义校验器、方法级校验</li><li>分页、排序、动态条件查询的接口设计</li><li>文件上传下载、静态资源、拦截器与过滤器、跨域、优雅停机</li></ul><p><strong>第 5 篇 · <a href="/backend-engineering-course/ch05/">安全：Spring Security 与 JWT 认证</a></strong></p><ul><li>过滤器链的执行顺序与短路机制：搞懂这条链，Security 的报错就不再神秘</li><li>基于 JWT 的无状态认证：登录、签发、校验、刷新、注销</li><li>方法级授权、基于角色与权限的访问控制</li><li>密码存储、CSRF、CORS 的实际配置，以及常见错误排查</li></ul><p><strong>第 6 篇 · <a href="/backend-engineering-course/ch06/">数据访问：SQL、JPA 与 MyBatis-Plus</a></strong></p><ul><li>数据源配置、连接池调参、HikariCP 的实战参数</li><li>Spring Data JPA：实体映射、派生查询、<code>@Query</code>、分页与排序</li><li>事务：传播行为、失效场景（自调用、私有方法、异常类型）、只读事务</li><li>N+1 问题的发现与三种解法；<code>open-in-view</code> 为什么必须关掉</li><li>MyBatis-Plus 接入 Spring Boot 4：starter 选择、分页插件注册的坑</li><li>SQL 初始化与版本化迁移（Flyway）；Redis 缓存与 NoSQL 要点</li></ul><p><strong>第 7 篇 · <a href="/backend-engineering-course/ch07/">缓存、校验与外部服务调用</a></strong></p><ul><li>缓存抽象：<code>@Cacheable</code> / <code>@CacheEvict</code>、key 生成规则、自调用陷阱，含 SQL 条数实测</li><li>缓存穿透、击穿、雪崩的区别与应对；多实例下的不一致问题</li><li>参数校验：<code>@Valid</code> 与 <code>@Validated</code> 的分工、分组校验、自定义约束</li><li>配置项校验：让配错在启动时就暴露</li><li><code>RestClient</code> 调用第三方接口：Boot 4 的模块拆分、超时配置、三类失败的分类处理</li><li>定时任务：<code>fixedDelay</code> 与 <code>fixedRate</code>、调度线程池、集群下的重复执行</li><li>邮件发送的超时陷阱；Quartz 与 <code>@Scheduled</code> 的取舍</li></ul><p><strong>第 8 篇 · <a href="/backend-engineering-course/ch08/">消息与实时通信：Kafka、AMQP 与 WebSocket</a></strong></p><ul><li>什么时候该上消息队列：解耦、削峰、异步的判断标准，以及不该上的情况</li><li>Kafka：Boot 4 新增的 <code>spring-boot-starter-kafka</code>、key 与分区的选择、偏移量提交</li><li>消费失败的处理：重试与死信主题（默认后缀 <code>-dlt</code>，含实测）</li><li>RabbitMQ：交换机模型、发布确认与退回、死信队列、JSON 消息转换器的新旧类取舍</li><li>WebSocket 与 STOMP：三种前缀的分工、客户端包名在 7.0 的迁移</li><li>三条链路的测试手法：起真 broker、不连 broker、连真端口</li></ul><h3 id="工程化" tabindex="-1">工程化 <a class="header-anchor" href="#工程化" aria-label="Permalink to &quot;工程化&quot;">​</a></h3><p><strong>第 9 篇 · <a href="/backend-engineering-course/ch09/">测试：单元测试、切片测试与 Testcontainers</a></strong></p><ul><li>测试分四层，附各层实测耗时</li><li>4.x 的测试模块拆分，以及一批切片注解的包名迁移对照表</li><li><code>@MockitoBean</code> 取代已删除的 <code>@MockBean</code>；<code>MockMvcTester</code> 的 AssertJ 写法与实测坑</li><li>四种 <code>webEnvironment</code> 的取舍；真实端口下 <code>@Transactional</code> 不回滚服务端数据</li><li>Testcontainers 2.0 的四项变化，以及拉不到 ryuk 镜像时的三种处理</li></ul><p><strong>第 10 篇 · <a href="/backend-engineering-course/ch10/">生产就绪：Actuator 与可观测性</a></strong></p><ul><li>端点默认暴露面与 <code>exposure.include</code>；未暴露的端点为什么返回 404 而不是 403</li><li>4.x 的三处搬迁：<code>HealthIndicator</code>、<code>MeterRegistryCustomizer</code>、<code>EndpointRequest</code></li><li>健康检查组件、存活与就绪探针、<code>info</code> 端点的开启条件</li><li>指标：注入注册表而非静态方法、低基数标签、Prometheus 命名转换</li><li>测试环境里真实指标导出被换成 <code>SimpleMeterRegistry</code> 这件事</li><li><code>loggers</code> 端点、自定义端点、端点安全的三道防线</li></ul><p><strong>第 11 篇 · <a href="/backend-engineering-course/ch11/">打包与部署：可执行 jar、容器与原生镜像</a></strong></p><ul><li>可执行 jar 的目录骨架与 MANIFEST 关键字段；依赖占了 99.6% 的体积</li><li>4.x 的 <code>jarmode</code> 从 <code>layertools</code> 换成 <code>tools</code>，<code>extract --layers</code> 的行为变化</li><li>分层索引按变化频率切四层的原理与实测启动耗时</li><li>AOT、CDS、两者叠加的效果与约束</li><li>镜像构建：<code>COPY --chown</code> 与 <code>COPY</code> 后 <code>chown</code> 的体积差异</li><li>Buildpacks 与 Dockerfile 路线的取舍</li><li>GraalVM 原生镜像：编译耗时、产物体积、启动时间与内存占用</li><li>上线前的配置：环境变量覆盖、容器内存感知、日志走标准输出</li></ul><h3 id="全端交付" tabindex="-1">全端交付 <a class="header-anchor" href="#全端交付" aria-label="Permalink to &quot;全端交付&quot;">​</a></h3><p><strong>第 12 篇 · 全端实战（一）：Vue 3 + Element Plus 前端</strong>（整理中）</p><ul><li>Vite 工程搭建与目录约定，与后端仓库如何组织</li><li>请求层封装：Axios 实例、拦截器、统一错误提示、Token 注入</li><li>路由与权限：动态菜单、登录守卫、按钮级权限</li><li>列表页范式：查询表格、分页、弹窗表单、批量操作</li></ul><p><strong>第 13 篇 · 全端实战（二）：联调、认证贯通与交付</strong>（整理中）</p><ul><li>开发期跨域与代理的三种解法，以及各自适用的场景</li><li>JWT 认证在全链路的贯通：登录、存储、刷新、失效处理</li><li>接口契约管理与文档（OpenAPI）自动生成</li><li>前后端一体化部署：Nginx 托管静态资源与反向代理</li><li>交付清单与验收自查表</li></ul><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><p>第一次读，建议按顺序从第 0 篇读起，尤其是第 3 篇的配置管理和第 6 篇的数据访问，这两块决定了后面所有章节的代码风格。</p><p>若带着具体问题来查，直接跳到对应篇章即可。每篇开头标注了对应的官方章节，遇到拿不准的地方回官方原文核对；每篇末尾有&quot;常见问题&quot;表，按&quot;症状、原因、解法&quot;列出来，报错时先查表。</p>',39)])])}const p=l(a,[["render",r]]);export{g as __pageData,p as default};
